/**
 * rate-limited throttle utility.
 *
 * Calls `fn` at most `maxPerWindow` times within every `windowMs` window;
 * excess calls are silently skipped.
 */

export interface ThrottleOptions {
  maxPerWindow: number;
  windowMs: number;
}

export function throttle<T extends (...args: never[]) => void>(
  fn: T,
  maxPerWindow: number,
  windowMs: number
): (...args: Parameters<T>) => void {
  const MAX_CALLS = maxPerWindow;
  const WINDOW_MS = windowMs;

  let lastCallTime = 0;
  let countInWindow = 0;

  const now = (): number => Date.now();

  return function throttled(...args: Parameters<T>): void {
    const current = now();
    const elapsed = current - lastCallTime;

    if (elapsed >= WINDOW_MS) {
      countInWindow = 0;
    }

    if (countInWindow >= MAX_CALLS) {
      // Excess call: silently skip.
      return;
    }

    countInWindow += 1;
    lastCallTime = current;
    fn(...args);
  };
}
```

