function throttle(fn, maxPerWindow, windowMs) {
  let lastTime = 0;
  let count = 0;
  return function (...args) {
    const now = Date.now();
    const sinceLast = now - lastTime;
    if (sinceLast >= windowMs) {
      count = 0;
    }
    if (count >= maxPerWindow) return;
    count++;
    lastTime = now;
    fn(...args);
  };
}
